-- Jeu de test : CBS « Amplitude » simulé (Oracle) pour les contrôles CCM sur population (§5, D3).
-- Reprend le schéma et les anomalies volontaires de infra/simulation/oracle/init/01-amplitude-simule.sh,
-- créés dans le schéma courant (pas de CREATE USER/GRANT ici). Le connecteur lit les vues V_AUDIT_*.

CREATE TABLE CBS_CLIENT (CLIENT_ID VARCHAR2(12) PRIMARY KEY, NOM VARCHAR2(100) NOT NULL, TYPE_CLIENT VARCHAR2(20) NOT NULL, AGENCE VARCHAR2(5) NOT NULL, DATE_CREATION DATE NOT NULL, STATUT VARCHAR2(10) NOT NULL);
CREATE TABLE CBS_COMPTE (COMPTE_ID VARCHAR2(20) PRIMARY KEY, CLIENT_ID VARCHAR2(12) NOT NULL REFERENCES CBS_CLIENT(CLIENT_ID), AGENCE VARCHAR2(5) NOT NULL, DEVISE CHAR(3) NOT NULL, TYPE_COMPTE VARCHAR2(10) NOT NULL, DATE_OUVERTURE DATE NOT NULL, DATE_DERNIER_MVT_CLIENT DATE, STATUT VARCHAR2(10) NOT NULL, SOLDE NUMBER(18,2) NOT NULL);
CREATE TABLE CBS_MOUVEMENT (MVT_ID NUMBER(18) PRIMARY KEY, COMPTE_ID VARCHAR2(20) NOT NULL REFERENCES CBS_COMPTE(COMPTE_ID), DATE_OPERATION DATE NOT NULL, DATE_VALEUR DATE NOT NULL, MONTANT NUMBER(18,2) NOT NULL, SENS CHAR(1) NOT NULL, CODE_OPERATION VARCHAR2(10) NOT NULL, UTILISATEUR_SAISIE VARCHAR2(10) NOT NULL, UTILISATEUR_VALIDATION VARCHAR2(10), CANAL VARCHAR2(10) NOT NULL);




CREATE VIEW V_AUDIT_COMPTES AS SELECT * FROM CBS_COMPTE;
CREATE VIEW V_AUDIT_MOUVEMENTS AS SELECT * FROM CBS_MOUVEMENT;
